<?php
require_once __DIR__.'/../../includes/bootstrap.php';require_roles(['ADMIN','RESPONSABLE','AGENT']);$db=Database::connection();$rows=$db->query("SELECT c.*,s.numero_souscription,p.nom produit,co.raison_sociale compagnie,cl.type_client,cl.nom,cl.prenom,cl.raison_sociale client_societe FROM contrats c JOIN souscriptions s ON s.id=c.souscription_id JOIN offres_devis o ON o.id=s.offre_id JOIN demandes_devis d ON d.id=o.demande_id JOIN clients cl ON cl.id=d.client_id JOIN produits_assurance p ON p.id=o.produit_id JOIN compagnies co ON co.id=p.compagnie_id ORDER BY c.created_at DESC")->fetchAll();$title='Contrats';require __DIR__.'/../../includes/header.php';?>
<div class="page-heading"><div><h1 class="h3">Portefeuille de contrats</h1><p class="text-secondary"><?= count($rows) ?> police(s)</p></div></div><div class="card"><div class="table-responsive"><table class="table table-hover align-middle mb-0"><thead><tr><th>Police</th><th>Client</th><th>Produit</th><th>Période</th><th>Prime</th><th>Statut</th></tr></thead><tbody><?php foreach($rows as $r): $client=$r['type_client']==='entreprise'?$r['client_societe']:trim($r['prenom'].' '.$r['nom']);?><tr><td class="fw-semibold"><?= e($r['numero_police']) ?></td><td><?= e($client) ?></td><td><?= e($r['produit']) ?><div class="small"><?= e($r['compagnie']) ?></div></td><td><?= date('d/m/Y',strtotime($r['date_effet'])) ?> → <?= date('d/m/Y',strtotime($r['date_echeance'])) ?></td><td><?= number_format((float)$r['prime_annuelle'],0,',',' ') ?> FCFA</td><td><span class="badge text-bg-success"><?= e($r['statut']) ?></span></td></tr><?php endforeach ?></tbody></table></div></div><?php require __DIR__.'/../../includes/footer.php'; ?>
